# Aggregate Root with immutable Value Object & optimistic version guard (Python)
from dataclasses import dataclass, field

@dataclass(frozen=True)
class Money:
    cents: int
    currency: str
    def __add__(self, other: 'Money') -> 'Money':
        if self.currency != other.currency:
            raise ValueError(f'Currency mismatch: {self.currency} vs {other.currency}')
        return Money(self.cents + other.cents, self.currency)

@dataclass
class Wallet:
    wallet_id: str
    balance: Money
    version: int
    events: list = field(default_factory=list)

    def withdraw(self, amount: Money) -> None:
        if amount.currency != self.balance.currency or amount.cents <= 0:
            raise ValueError('Invalid withdrawal')
        if self.balance.cents < amount.cents:
            raise ValueError('Insufficient funds')
        self.balance = Money(self.balance.cents - amount.cents, self.balance.currency)
        self.events.append({'type': 'FundsWithdrawn', 'wallet_id': self.wallet_id, 'cents': amount.cents})
